import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        print("true")
        return
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for ch in s:
        if ch in mapping.values():
            stack.append(ch)
        elif ch in mapping:
            if not stack or stack[-1] != mapping[ch]:
                print("false")
                return
            stack.pop()
    print("true" if len(stack) == 0 else "false")

if __name__ == '__main__':
    solve()

