#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main() {
    char s[100005];
    if (scanf("%s", s) != 1) {
        printf("true\n");
        return 0;
    }
    int len = strlen(s);
    char stack[100005];
    int top = -1;
    for (int i = 0; i < len; i++) {
        char c = s[i];
        if (c == '(' || c == '{' || c == '[') {
            stack[++top] = c;
        } else {
            if (top == -1) { printf("false\n"); return 0; }
            char open = stack[top--];
            if ((c == ')' && open != '(') ||
                (c == '}' && open != '{') ||
                (c == ']' && open != '[')) {
                printf("false\n");
                return 0;
            }
        }
    }
    printf(top == -1 ? "true\n" : "false\n");
    return 0;
}
